/**
 * R-1850 — the directors register (company_directors) and its two RPCs
 * (migration 20261024201000_r1850_company_directors.sql). Writes only through the RPCs, which
 * check the role, the company and the business type (Pvt Ltd / not set).
 *
 * Reads go through the data gateway, which masks email / phone for a role without
 * can_view_contact_details (contact-mask.ts CONTACT_COLUMNS.company_directors); a masked value
 * sent back on save keeps the stored one (the RPC's own rule).
 *
 * Untyped client: the table and functions are newer than database.types.ts (shared,
 * regenerated by the manager after the migration lands).
 */
"use client";

import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import type { SupabaseClient } from "@supabase/supabase-js";
import { toast } from "sonner";

import { createClient } from "@/lib/supabase/client";
import { useCurrentUser } from "@/lib/hooks/useCurrentUser";
import { toastError } from "@/lib/errors/toast-error";
import type { CompanyDirector, DirectorSaveInput } from "@/lib/company/directors";

const untyped = () => createClient() as unknown as SupabaseClient;

export const COMPANY_DIRECTORS_KEY = ["company_directors"] as const;

/** Code deployed before the migration: no directors to show, the screen still works. */
export function isCompanyDirectorsTableMissing(err: unknown): boolean {
  const m = err instanceof Error ? err.message : String(err ?? "");
  return /company_directors/.test(m) && /(does not exist|could not find|schema cache)/i.test(m);
}

/** Every director of the company (current and ceased), by name. A failed read is an error. */
export function useCompanyDirectors(enabled = true) {
  const me = useCurrentUser();
  const tenantId = me.data?.tenantId ?? null;
  return useQuery({
    queryKey: [...COMPANY_DIRECTORS_KEY, tenantId],
    enabled: enabled && Boolean(tenantId),
    queryFn: async (): Promise<CompanyDirector[]> => {
      const { data, error } = await untyped()
        .from("company_directors")
        .select("id, name, din, pan, designation, appointed_on, ceased_on, dsc_expiry, last_kyc_year, email, phone")
        .order("name", { ascending: true });
      if (error) {
        if (isCompanyDirectorsTableMissing(error.message)) return [];
        throw new Error(error.message);
      }
      return ((data ?? []) as CompanyDirector[]).map((d) => ({
        ...d,
        last_kyc_year: d.last_kyc_year == null ? null : Number(d.last_kyc_year),
      }));
    },
  });
}

export function useSaveCompanyDirector() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: async (input: DirectorSaveInput & { id: string | null }) => {
      const { data, error } = await untyped().rpc("save_company_director", {
        p_id: input.id,
        p_name: input.name,
        p_din: input.din,
        p_pan: input.pan,
        p_designation: input.designation,
        p_appointed_on: input.appointed_on,
        p_ceased_on: input.ceased_on,
        p_dsc_expiry: input.dsc_expiry,
        p_last_kyc_year: input.last_kyc_year,
        p_email: input.email,
        p_phone: input.phone,
      });
      if (error) throw new Error(error.message);
      return data as string;
    },
    onSuccess: (_d, input) => {
      void qc.invalidateQueries({ queryKey: COMPANY_DIRECTORS_KEY });
      toast.success(input.id ? `${input.name} updated` : `${input.name} added to the directors register`);
    },
    onError: (err) => toastError(err, { fallback: "Couldn't save the director" }),
  });
}

export function useDeleteCompanyDirector() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: async (id: string) => {
      const { error } = await untyped().rpc("delete_company_director", { p_id: id });
      if (error) throw new Error(error.message);
    },
    onSuccess: () => {
      void qc.invalidateQueries({ queryKey: COMPANY_DIRECTORS_KEY });
      toast.success("Director removed");
    },
    onError: (err) => toastError(err, { fallback: "Couldn't remove the director" }),
  });
}
